import sys, collections as C
from datetime import timedelta
sys.path.insert(0, sys.argv[1] + '/code')
from data_loader import load_dataset

ds = load_dataset(names=('sample_requests', 'sample_output', 'activity', 'requests'))
wf = sorted((a for a in ds['activity'].rows if a['source_system'] == 'deletion_worker'), key=lambda a: a['event_time'])
lo_h, hi_h = float(sys.argv[2]), float(sys.argv[3])
gold = {r['case_id']: r['steps_json'] for r in ds['sample_output'].rows}
for name in ('sample_requests', 'requests'):
    cnt = C.Counter()
    for req in ds[name].rows:
        rep = req['reported_at']
        cands = [a for a in wf if a['event_type'] == 'DELETE_RECORD' and a['resource_id'].startswith('account_')
                 and rep + timedelta(hours=lo_h) <= a['event_time'] <= rep + timedelta(hours=hi_h)]
        cnt[len(cands)] += 1
        if name == 'sample_requests':
            g = {s['resource_id'] for s in gold[req['case_id']]}
            ok = [a['resource_id'] in g for a in cands]
            if ok != [True]:
                print(req['case_id'], [(a['resource_id'], a['event_time'].strftime('%H:%M')) for a in cands], ok)
    print(name, 'candidates per case', sorted(cnt.items()))
# which other workflow events (non-account) are in gold, and their offset from the account event / reported_at
offs = C.Counter()
for req in ds['sample_requests'].rows:
    g = {s['resource_id'] for s in gold[req['case_id']]}
    for a in wf:
        if a['resource_id'] in g and not a['resource_id'].startswith('account_'):
            offs[(a['event_type'], round((a['event_time'] - req['reported_at']).total_seconds() / 3600, 1))] += 1
print(sorted(offs.items(), key=lambda kv: kv[0][1]))

