class WorkflowAccounts:
    """Primary profiles the deletion workflow acted on, assigned to cases.

    A request's workflow deletes the account profile just before reporting,
    so DELETE_RECORD activity on account_* inside WORKFLOW_WINDOW around
    reported_at are the candidates. Accounts the evidence ties to a user go
    to that user's cases and are removed from every other case; then any case
    left with a single candidate takes it, repeatedly. Ambiguous cases get no
    workflow account rather than a guess.
    """

    def __init__(self, dataset: Dataset, identities: IdentityIndex, index: EvidenceIndex,
                 requests: list[dict]):
        deletes = sorted(
            (a for a in dataset["activity"].rows
             if a["event_type"] == "DELETE_RECORD" and a["source_system"] == "deletion_worker"
             and a["resource_id"].startswith("account_")),
            key=lambda a: a["event_time"]) if "activity" in dataset.tables else []
        owners = {rid: self._owners(rid, identities, index) for rid in {a["resource_id"] for a in deletes}}

        candidates: dict[str, set[str]] = {}
        users: dict[str, str] = {}
        for req in requests:
            if not classify_request(req["request_text"]).authorizes_deletion:
                continue
            res = identities.resolve("email", req["email"], req["requested_at"])
            if res.user_id is None:
                continue
            users[req["case_id"]] = res.user_id
            lo, hi = req["reported_at"] + WORKFLOW_WINDOW[0], req["reported_at"] + WORKFLOW_WINDOW[1]
            candidates[req["case_id"]] = {a["resource_id"] for a in deletes
                                          if lo <= a["event_time"] <= hi}

        assigned: dict[str, set[str]] = defaultdict(set)
        for case_id, cands in candidates.items():
            for rid in list(cands):
                if owners[rid]:
                    cands.discard(rid)
                    if owners[rid] == {users[case_id]}:
                        assigned[case_id].add(rid)
        changed = True
        while changed:
            changed = False
            for case_id, cands in candidates.items():
                if case_id in assigned or len(cands) != 1:
                    continue
                rid = next(iter(cands))
                assigned[case_id].add(rid)
                for other, other_cands in candidates.items():
                    if other != case_id and rid in other_cands:
                        other_cands.discard(rid)
                changed = True
        self.assigned = dict(assigned)

    @staticmethod
    def _owners(resource_id: str, identities: IdentityIndex, index: EvidenceIndex) -> set[str]:
        owners: set[str] = set()
        for obs in index.history(resource_id):
            if obs.kind == "activity":
                continue
            for kind, value in obs.all_identifiers:
                if kind == "user" and value in identities.identities:
                    owners.add(value)
                elif kind in ("email", "phone", "email_hash"):
                    owners |= identities.owners(kind, value)
        return owners

    def accounts_for(self, case_id: str) -> set[str]:
        return self.assigned.get(case_id, set())


class DeletionEngine:
    # Link resources only through evidence observed after the request was
    # made; older sightings describe accounts as they were before deletion
    # was asked for. Their state is still read from the full history.
    discover_from_request = True

    def __init__(self, dataset: Dataset, identities: IdentityIndex | None = None,
                 index: EvidenceIndex | None = None, requests: list[dict] | None = None):
        self.dataset = dataset
        self.identities = identities or build_identity_index(dataset)
        self.index = index or build_evidence_index(dataset)
        self.rules = load_rules(dataset)
        if requests is None:
            requests = [r for name in ("requests", "sample_requests") if name in dataset.tables
                        for r in dataset[name].rows]
        self.workflow = WorkflowAccounts(dataset, self.identities, self.index, requests)

    # -- discovery ---------------------------------------------------------

    def discover(self, keys: set, request: dict) -> dict[str, list[Observation]]:
        at = request["audit_at"]
        found: dict[str, list[Observation]] = defaultdict(list)
        for obs in self.index.matching(keys, at):
            if obs.kind == "activity" or not obs.resource_id:
                continue
            if self.discover_from_request and obs.observed_at < request["requested_at"]:
                continue
            own_strong = {i for i in obs.identifiers if i[0] in STRONG_KINDS}
            # A record that holds someone else's identifiers and only matched
            # through its lookup context belongs to that other subject.
            if own_strong and not own_strong & keys:
                continue
            found[obs.resource_id].append(obs)
        for rid in self.workflow.accounts_for(request["case_id"]):
            found.setdefault(rid, [])
        return found

    # -- assessment --------------------------------------------------------

    def assess(self, resource_id: str, keys: set, at: datetime,
               not_before: datetime | None = None) -> Assessment:
        history = [o for o in self.index.history(resource_id, at) if o.kind != "activity"]
        system = system_for_resource(resource_id) or next(
            (o.system_id for o in history if o.system_id), "unknown")
        category = categorize(resource_id, history)
        action = self.rules.get(category, "DELETE")

